#!/usr/bin/env python3
"""Generate a portable Module using existing AM actions and Viewer blocks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
DEST=(ROOT.parents[1] / 'daily-routine')/'agents/main'
def dump(path,data):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def code(id,body,out):return {'id':id,'type':'code_execution','code':body,'output_key':out}
def tool(id,name,params,out):return {'id':id,'type':'tool_call','tool':name,'params':params,'output_key':out}
def call(id,wf,inp,out):return {'id':id,'type':'workflow_call','workflow_id':wf,'workflow_version':'3' if wf=='daily-role-read' else '2','execution':'sync','input':inp,'output_key':out}
def field(name,title,kind='string',options=None):
    x={'name':name,'title':title,'type':kind,'required':True}
    if options:x['options']=[{'value':v,'label':l}for v,l in options]
    return x
def wf(id,title,actions,output,fields=None):
    x={'$schema':'agentmaurice.workflow/v2','schema_version':2,'kind':'workflow','workflow_id':id,'version':'2','title':title,'actions':actions,'output':output}
    if fields:x['forms']=[{'id':'submit','title':title,'fields':fields,'actions_on_submit':[a['id']for a in actions]}]
    dump(DEST/'workflows'/(id+'.json'),x);return x
JEUX=[('usage','Actual measurements'),('qualification','Test data')]
BOOL=[('non','No'),('oui','Yes')]
DIMS=[('execution_minutes','Work (minutes)'),('relecture_minutes','Review (minutes)'),('correction_minutes','Corrections (minutes)'),('supervision_minutes','Supervision (minutes)'),('maintenance_minutes','Allocated recurring maintenance (minutes)'),('installation_minutes','Allocated initial setup (minutes)')]
def app(id,title,workflow,fields,layout,extra=None,defaults=None):
    props={f['name']:{'type':['number','string']if f['type']=='number'else'string'}for f in fields}
    props.update({k:{'type':'object'}for k in ['result','listing','selected']})
    initial={f['name']:0 if f['type']=='number'else''for f in fields};initial.update({'result':{'message':'No entry recorded.'},'listing':{'items':[]},'selected':{'content':''}});initial.update(defaults or{})
    events=[{'event_id':'submit','trigger':'form.submit','workflow':{'workflow_id':workflow,'input':{f['name']:'{{ state.'+f['name']+' }}'for f in fields}},'result_to_state':'result'}]+(extra or[])
    x={'$schema':'agentmaurice.miniapp/v2','schema_version':2,'kind':'miniapp','miniapp_id':id,'version':'2','title':title,'description':'Internal manual routine; no sending or publication.','ui':{'renderer':'component','component':'daily-routine','configuration':{'layout':layout}},'state_schema':{'type':'object','properties':props},'initial_state':initial,'events':events}
    dump(DEST/'miniapps'/(id+'.json'),x)
def text(value):return {'type':'text','value':value}
def bound(path):return {'state':path}
def build():
    js=(ROOT/'metrics.js').read_text().replace('export ','')
    fields=[field('jeu','Data set','select',JEUX),field('session_id','Measurement ID (reuse to correct)'),field('comparaison_id','Comparison pair'),field('date','Work date','date'),field('phase','Method','select',[('reference','Baseline without AM assistance'),('assiste','With AM assistance')]),field('dossier_id','Local case or deliverable'),field('categorie','Comparable work type'),field('complexite','Complexity','select',[('courte','Short'),('standard','Standard'),('complexe','Complex')]),field('critere_qualite','Quality criterion set before work','text'),field('qualite','Reviewed quality','select',[('a_revoir','Needs review'),('valide','Validated for this internal objective'),('rejete','Rejected')]),field('mesure_ref','Time record reference'),field('prochaine_etape','Next step / blocker','text')]+[field(k,v,'number')for k,v in DIMS]+[field('temps_observe','Time actually recorded (not an estimate)','select',BOOL),field('confirmation_manuelle','Confirm this entry or correction','select',BOOL)]
    wf('daily-time-save','Record time spent',[
      code('validate',js+'\n\n\nreturn validateEntry({{ json . }});','record'),
      tool('save','write_file',{'path':'/company-in-a-box/daily/{{ record.jeu }}/{{ record.session_id }}.json','content':'{{ .record | json }}','overwrite':True},'saved')
    ],{'record':'{{ record }}','message':'Time recorded. A gain requires a comparable baseline and two quality-validated deliverables.','external_effect':False},fields)
    validate='const x=({{ json . }}).entry || ({{ json . }}); if(!["usage","qualification"].includes(x.jeu)||typeof x.session_id!=="string"||!/^[a-z0-9][a-z0-9-]{0,63}$/.test(x.session_id)) throw new Error("invalid_time_record_ref"); return {jeu:x.jeu,session_id:x.session_id};'
    wf('daily-time-read','Review a measurement',[
      code('validate',validate,'request'),tool('read','read_file',{'path':'/company-in-a-box/daily/{{ request.jeu }}/{{ request.session_id }}.json'},'stored'),
      code('decode','const r=JSON.parse(({{ json .stored }}).content);const q={{ json .request }};if(r.session_id!==q.session_id||r.jeu!==q.jeu||r.schema_version!==1)throw new Error("stored_measurement_mismatch");return {record:r,content:JSON.stringify(r,null,2)};','detail')
    ],{'record':'{{ detail.record }}','content':'{{ detail.content }}'})
    report_fields=[field('jeu','Data set','select',JEUX),field('date_debut','Start (include the baseline period)','date'),field('date_fin','End','date')]
    wf('daily-report','Observed time report',[
      code('validate','const x={{ json . }};function date(v){return typeof v==="string"&&/^\\d{4}-\\d{2}-\\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;}if(!["usage","qualification"].includes(x.jeu)||!date(x.date_debut)||!date(x.date_fin)||x.date_debut>x.date_fin)throw new Error("invalid_report_period");return {jeu:x.jeu,date_debut:x.date_debut,date_fin:x.date_fin};','request'),
      tool('list','list_files',{'path':'/company-in-a-box/daily/{{ request.jeu }}'},'files'),
      code('entries','const files={{ json .files }};const q={{ json .request }};if(!Array.isArray(files))throw new Error("invalid_time_listing");const entries=files.filter(f=>typeof f.path==="string"&&f.path.endsWith(".json")).map(f=>({session_id:f.path.split("/").pop().replace(/\\.json$/,""),jeu:q.jeu}));if(entries.length>100)throw new Error("time_journal_limit_100_exceeded");return entries;','entries'),
      {'id':'read','type':'for_each','items':'{{ entries }}','item_key':'entry','max_items':100,'on_empty':'continue','workflow_id':'daily-time-read','output_key':'records'},
      code('summary',js+'\n\n\nconst all={{ json .records }};const entries={{ json .entries }};if(all===null&&entries.length===0)return summarize([],{{ json .request }});if(!Array.isArray(all))throw new Error("invalid_time_records");return summarize(all.map(x=>x.record),{{ json .request }});','report')
    ],{'items':'{{ report.items }}','pairs':'{{ report.pairs }}','exclusions':'{{ report.exclusions }}','summary':'{{ report.summary }}','message':'{{ report.message }}','manual_only':True,'external_effect':False},report_fields)
    context_fields=[field('dossier_id','Local case'),field('proposal_id','Memory revision to view')]
    wf('daily-context','Prepare my case with memory',[
      call('dossier','daily-role-read',{'dossier_id':'{{ dossier_id }}'},'local'),call('memory','company-memory-query',{'proposal_id':'{{ proposal_id }}'},'memory'),
      code('context','const r=({{ json .local }}).data.record;const m=({{ json .memory }}).data;const valid=m.status==="validated"&&typeof m.answer==="string"&&m.answer.trim()&&Array.isArray(m.citations)&&m.citations.length>0&&Number.isFinite(Date.parse(m.expires_at))&&Date.parse(m.expires_at)>Date.now();return {dossier:r,content:JSON.stringify(r,null,2),memory_status:m.status,memory_answer:valid?m.answer:"Memory cannot be used: review is required.",citations:valid?m.citations:[],proposal_id:m.proposal_id,expires_at:m.expires_at||"",ready:!!valid,message:valid?"Context available. Prepare and review the internal deliverable before recording time.":"Memory is unvalidated or expired: do not use it as fact. Return to collection or memory review."};','context')
    ],{'dossier':'{{ context.dossier }}','content':'{{ context.content }}','memory_status':'{{ context.memory_status }}','memory_answer':'{{ context.memory_answer }}','citations':'{{ context.citations }}','proposal_id':'{{ context.proposal_id }}','expires_at':'{{ context.expires_at }}','ready':'{{ context.ready }}','message':'{{ context.message }}','manual_only':True,'external_effect':False},context_fields)
    app('daily-time-console','Time log','daily-time-save',fields,[text('Measure actual human time excluding breaks. Allocate each minute to one case. Reusing an ID corrects the record rather than adding one.'),text(bound('result.message')),text('Recurring human time (minutes)'),text(bound('result.record.temps_humain_minutes')),text('Initial setup (minutes), excluded from recurring gain'),text(bound('result.record.installation_minutes'))],defaults={'jeu':'usage','phase':'reference','complexite':'standard','qualite':'a_revoir','temps_observe':'non','confirmation_manuelle':'non'})
    app('daily-report-console','Time briefing and report','daily-report',report_fields,[text('Descriptive report: test data does not prove a real gain. Both periods must be included.'),text(bound('result.message')),{'type':'metric','label':'Recurring gain (minutes)','value':bound('result.summary.gain_minutes')},{'type':'metric','label':'Setup (minutes)','value':bound('result.summary.installation_minutes')},{'type':'metric','label':'Total human time (minutes)','value':bound('result.summary.total_temps_humain_minutes')},text('Measurements excluded from comparison'),{'type':'table','columns':['comparaison_id','reason_label'],'column_labels':{'comparaison_id':'Comparison','reason_label':'Reason'},'rows':bound('result.exclusions')},{'type':'table','columns':['session_id','date','phase_label','dossier_id','quality_label','temps_humain_minutes','prochaine_etape'],'column_labels':{'session_id':'Measurement','date':'Date','phase_label':'Method','dossier_id':'Case','quality_label':'Quality','temps_humain_minutes':'Human minutes','prochaine_etape':'Next step'},'rows':bound('result.items'),'on_row_click':'select'},text('Selected measurement'),text(bound('selected.content'))],[{'event_id':'select','trigger':'table.row_click','workflow':{'workflow_id':'daily-time-read','input':{'session_id':'{{ event.payload.item.session_id }}','jeu':'{{ state.jeu }}'}},'result_to_state':'selected'}],{'jeu':'usage','result':{'items':[],'exclusions':[],'message':'No period viewed.'}})
    app('daily-context-console','My routine — case and memory', 'daily-context',context_fields,[{'type':'steps','items':[{'title':'Choose a case','description':'Watch: dated source. Content: internal draft. Support: next assistance to prepare.','status':'todo'},{'title':'View memory','description':'Find a revision and check its date and citations.','status':'todo'},{'title':'Prepare and review','description':'Use the role screens. A prepared draft does not prove publication or a successful trial.','status':'todo'},{'title':'Record time and feedback','description':'Record time, then propose an excerpt to memory. Memory review remains separate.','status':'todo'}]},text(bound('result.message')),text('Local case'),text(bound('result.content')),text('Memory'),text(bound('result.memory_status')),text(bound('result.memory_answer')),text('Revision'),text(bound('result.proposal_id')),text('Sources'),text(bound('result.citations')),text('Review before'),text(bound('result.expires_at'))])
    manifest={'$schema':'agentmaurice.module/v2','schema_version':2,'key':'cib-daily-routine','name':'Daily routine — cases, memory and time','version':'0.1.1','provides':{'actions':[{'key':'daily-time-save','workflow_id':'daily-time-save','workflow_version':'2'}],'queries':[{'key':n,'workflow_id':n,'workflow_version':'2'}for n in ['daily-time-read','daily-report','daily-context']],'apps':[{'key':n,'miniapp_id':n,'miniapp_version':'2'}for n in ['daily-time-console','daily-report-console','daily-context-console']]},'requires':{}}
    dump((ROOT.parents[1] / 'daily-routine')/'module.yaml',manifest)
if __name__=='__main__':build()
